# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
G, GI, R, C, M = "Graziella", "Giulia", "Renzo", "Chiara", "Matteo"
D = [
("#", "Scena 1 — Domenica 14 settembre, ore 8. Lo studio di Paolo, casa Corsini.", "장면 1 — 9월 14일 일요일 오전 8시. 코르시니 가, 파올로의 서재."),
(None, "Graziella apre il cassetto della scrivania di Paolo per prendere l'accordo di febbraio: Mancini lo vuole lunedì, per l'offerta della Maison. Sotto la penna dal cappuccio d'argento e sotto i fogli firmati c'è una busta ingiallita. Sopra, la calligrafia stretta e inclinata di Ugo: « A Paolo ». Sul retro, a matita, la scrittura di Paolo: « Per i ragazzi, quando litigheranno ».", "그라치엘라가 2월 합의서를 꺼내려고 파올로의 책상 서랍을 연다. 만치니 변호사가 메종의 제안 때문에 월요일까지 달라고 했다. 은빛 뚜껑 만년필과 서명된 서류 밑에 누렇게 바랜 봉투가 하나 있다. 겉면엔 우고의 좁고 비스듬한 글씨로 '파올로에게'. 뒷면엔 연필로 쓴 파올로의 글씨. '아이들에게, 싸울 때.'"),
(G, "(a voce bassa) Paolo... Quanti anni l'hai tenuta qui sotto?", "(작은 목소리로) 파올로… 이걸 몇 년이나 여기 밑에 두고 있었어요?"),
(GI, "(sulla porta, in pigiama) Nonna? Con chi parli?", "(잠옷 차림으로 문간에서) 할머니? 누구랑 얘기해요?"),
(G, "Con tuo nonno. Ogni tanto gli rispondo, quando trovo le sue cose.", "네 할아버지랑. 그분 물건을 찾으면 가끔 대답해 드리거든."),
(GI, "Cos'hai trovato?", "뭘 찾으셨어요?"),
(G, "Una lettera. Del bisnonno Ugo al nonno Paolo. C'è la data: tre ottobre millenovecentonovantasei.", "편지야. 증조할아버지 우고가 할아버지 파올로에게 쓴 거. 날짜가 있네. 1996년 10월 3일."),
(GI, "Novantasei... L'anno della prima firma con la Maison.", "96년… 메종이랑 처음 서명한 해잖아요."),
(G, "Come lo sai?", "그걸 어떻게 알아?"),
(GI, "Lo zio Matteo ha raccontato la storia del sugo di cinghiale troppo salato. La sera prima della firma.", "마테오 삼촌이 너무 짠 멧돼지 소스 이야기를 해 줬어요. 서명 전날 밤이요."),
(G, "(sorride appena) Quel sugo non lo mangiò nessuno. Tuo nonno era così nervoso che salò due volte.", "(살짝 웃으며) 그 소스는 아무도 못 먹었지. 할아버지가 너무 긴장해서 소금을 두 번 넣었거든."),
(GI, "La apri?", "열어 보실 거예요?"),
(G, "È già aperta. Lui l'ha letta. E poi ci ha scritto sopra: « Per i ragazzi, quando litigheranno ».", "이미 열려 있어. 할아버지는 읽으셨어. 그리고 위에 이렇게 쓰셨지. '아이들에게, 싸울 때.'"),
(GI, "Allora è per adesso.", "그럼 지금이네요."),
(G, "Sì. Credo che sia per adesso.", "그래. 지금인 것 같구나."),
(GI, "Leggila, nonna.", "읽어 보세요, 할머니."),
(G, "No. Non da sola. Questa lettera non si legge da soli.", "아니. 혼자서는 안 돼. 이 편지는 혼자 읽는 게 아니야."),
(GI, "Chiamo lo zio e la zia?", "삼촌이랑 고모 부를까요?"),
(G, "Dopo. Prima chiamo un'altra persona.", "나중에. 먼저 다른 사람을 부를 거야."),
(GI, "Chi?", "누구요?"),
(None, "Graziella prende il telefono fisso, quello con la rotella, che nessuno usa più. Compone un numero a memoria.", "그라치엘라가 아무도 쓰지 않는 다이얼식 유선 전화기를 든다. 외우고 있는 번호를 돌린다."),
(G, "Renzo? Sono la signora Corsini. ... No, non è successo niente. Cioè, sì. Venga a casa, per favore. Alle dieci. ... Lo so che ha dato le dimissioni. Non La chiamo come presidente.", "렌초? 코르시니 부인이에요. … 아뇨, 아무 일 없어요. 아니, 있어요. 집으로 와 주세요, 부탁해요. 10시에. … 사직서 내신 거 알아요. 회장으로서 부르는 게 아니에요."),
(GI, "E come chi lo chiami?", "그럼 누구로서 부르시는 거예요?"),
(G, "Come la nuora di Ugo. È l'unica che può leggere questa lettera con lui.", "우고의 며느리로서. 이 편지를 그분이랑 같이 읽을 수 있는 건 나뿐이야."),

("#", "Scena 2 — Ore 10. Il salotto.", "장면 2 — 오전 10시. 거실."),
(None, "Renzo arriva in giacca, con il cappello in mano, come nei giorni di festa. Non è più entrato in casa Corsini dal giorno delle dimissioni. Si siede sul bordo della poltrona.", "렌초가 명절날처럼 재킷을 입고 모자를 손에 든 채 온다. 사직서를 낸 날 이후 코르시니 가에 처음 들어온다. 안락의자 끝에 걸터앉는다."),
(R, "Signora, se è per le chiavi, le ha la Chiara. Io non torno indietro.", "부인, 열쇠 때문이라면 키아라가 갖고 있어요. 전 돌아가지 않습니다."),
(G, "Non è per le chiavi. È per questa. (gli porge la busta)", "열쇠 때문이 아니에요. 이것 때문이에요. (봉투를 건넨다)"),
(R, "(la guarda a lungo) È la scrittura del signor Ugo.", "(오래 바라보며) 우고 사장님 글씨네요."),
(G, "Dell'ottobre del novantasei. Dopo un'estate intera a decidere. La sera prima che mio marito andasse a Parigi.", "96년 10월이에요. 여름 내내 고민한 끝에요. 남편이 파리에 가기 전날 밤이요."),
(R, "Me la ricordo, quella sera. Padre e figlio non si parlavano da quaranta giorni: li contavo io, sul calendario del laboratorio. « Così diventiamo le mani di qualcun altro », diceva lui. « Così mangiamo », diceva suo marito. Quella sera il signor Ugo restò in laboratorio fino a tardi, senza dire una parola. Poi andò a casa e si chiuse in cucina.", "그날 밤 기억나요. 부자가 40일째 말을 안 하고 있었어요. 제가 공방 달력에 날짜를 세고 있었거든요. 우고 사장님은 '이러면 우린 남의 손이 된다'고 하셨고, 부인 남편분은 '이러면 먹고산다'고 하셨죠. 그날 밤 우고 사장님은 한마디도 없이 공방에 늦게까지 계셨어요. 그러다 집에 가서 부엌에 틀어박히셨죠."),
(G, "A scrivere questa.", "이걸 쓰시려고요."),
(R, "Io non lo sapevo. Credevo che fosse arrabbiato con tutti.", "전 몰랐어요. 다들한테 화가 나신 줄 알았죠."),
(G, "Forse lo era. La legga Lei, Renzo. Ad alta voce. Io non ce la faccio a leggere la voce di mio suocero.", "그러셨을 수도 있죠. 렌초가 읽어 주세요. 소리 내서요. 시아버님 목소리를 제가 읽을 자신이 없어요."),
(R, "(si mette gli occhiali, apre il foglio) « Caro Paolo, sono quaranta giorni che non ci parliamo, e domani firmerai con i francesi. Io a Parigi non verrò: sai che gli aerei non mi piacciono e che le firme degli altri le guardo male. »", "(안경을 쓰고 종이를 펼친다) '사랑하는 파올로에게. 우리가 말을 안 한 지 40일이 됐구나. 그리고 내일 너는 프랑스 사람들과 서명하겠지. 나는 파리에 가지 않겠다. 내가 비행기를 싫어하는 것도, 남의 서명을 못마땅하게 보는 것도 알 테지.'"),
(GI, "(dalla porta, piano) Sembra lui che parla.", "(문간에서 작게) 할아버지가 말하는 것 같아요."),
(R, "« Ti scrivo, invece di parlarti, perché a voce litigheremmo. E io sono troppo vecchio per voler vincere le discussioni. »", "'말로 하는 대신 글을 쓴다. 말로 하면 우리는 다툴 테니까. 그리고 나는 말다툼에서 이기고 싶어 하기엔 너무 늙었다.'"),
(G, "Questo lo diceva sempre. « Alla mia età si vince solo a briscola. »", "그 말 늘 하셨어요. '내 나이엔 브리스콜라에서나 이기는 거다.'"),
(R, "« Quando aprii il laboratorio, nel cinquantotto, avevo una macchina da cucire, un banco e un timbro. Il timbro lo feci fare prima ancora di avere un cliente, perché pensavo che un nome bisognasse averlo prima di meritarlo. »", "'1958년 공방을 열었을 때 내게는 재봉틀 한 대, 작업대 하나, 도장 하나가 있었다. 도장은 손님이 생기기도 전에 만들었다. 이름이란 받을 자격을 갖추기 전에 먼저 가져야 한다고 생각했으니까.'"),
(G, "Il timbro... quello che Chiara ha portato a Milano.", "도장… 키아라가 밀라노에 가져갔던 그거."),
(R, "« Mi sbagliavo. Il nome si fa con le mani; la carta viene dopo. »", "'내가 틀렸다. 이름은 손으로 만드는 것이고, 종이는 그다음이다.'"),
(G, "(chiude gli occhi) È la frase del suo quaderno. Chiara l'ha trovata a febbraio.", "(눈을 감으며) 그분 스케치북에 있던 문장이에요. 키아라가 2월에 찾았죠."),
(R, "« Tu domani farai una cosa che io non ebbi il coraggio di fare: metterai il nostro lavoro sotto il nome di un altro. Non ti giudico. Centocinquanta famiglie mangiano. Prima si mangia, poi si vive. »", "'내일 너는 내가 할 용기가 없던 일을 할 것이다. 우리 일을 남의 이름 밑에 두는 일. 너를 탓하지 않는다. 백오십 가구가 먹고산다. 먼저 먹고, 그다음에 사는 것이다.'"),
(GI, "Non era arrabbiato, allora.", "그럼 화나신 게 아니었네요."),
(G, "Era arrabbiato e d'accordo insieme. Succede, nelle famiglie.", "화도 나고 동의도 하셨던 거야. 가족끼리는 그런 일이 있어."),
(R, "« Ma ti chiedo tre cose, e vorrei che tu le scrivessi da qualche parte dove i tuoi figli possano trovarle. »", "'하지만 세 가지를 부탁한다. 그리고 네 아이들이 찾을 수 있는 곳에 그걸 적어 두었으면 한다.'"),
(G, "Le ha messe qui. Sotto la sua penna. Dove nessuno guarda finché non serve.", "여기 두셨네요. 그분 펜 밑에. 필요할 때까지 아무도 안 보는 곳에."),
(R, "« La prima: che il timbro non esca mai da questa casa, e che non lo si venda a nessuno. Nemmeno ai francesi. »", "'첫째, 도장은 절대 이 집 밖으로 나가지 않게 할 것. 누구에게도 팔지 말 것. 프랑스 사람들에게도.'"),
(G, "(sottovoce) Nemmeno ai francesi. E loro adesso vogliono il quaranta per cento.", "(작게) 프랑스 사람들에게도. 그런데 그 사람들이 지금 40%를 원해요."),
(R, "« La seconda: che resti sempre un banco, uno solo, dove si facciano borse nostre, anche se nessuno le compra. »", "'둘째, 언제나 작업대 하나만은 남겨 둘 것. 아무도 사지 않더라도 우리 가방을 만드는 작업대 하나.'"),
(None, "Renzo si ferma. Gira il foglio. Le mani gli tremano un poco.", "렌초가 멈춘다. 종이를 넘긴다. 손이 조금 떨린다."),
(G, "Vada avanti, Renzo.", "계속 읽어 주세요, 렌초."),
(R, "(la voce cambia) « Quel banco lo do a Renzo. Finché Renzo siede a quel banco, il nome è al sicuro. »", "(목소리가 달라진다) '그 작업대는 렌초에게 준다. 렌초가 그 작업대에 앉아 있는 한, 이름은 안전하다.'"),
(None, "Silenzio. Giulia si mette una mano sulla bocca. Renzo toglie gli occhiali e li pulisce con il fazzoletto, anche se sono puliti.", "침묵. 줄리아가 손으로 입을 가린다. 렌초가 안경을 벗어 깨끗한데도 손수건으로 닦는다."),
(G, "Lei non lo sapeva.", "모르셨던 거죠."),
(R, "Lo sapevo solo a metà, signora. Nel novantasette me lo disse a voce: « Renzo, non far sparire le borse nostre. Tienine sempre una sul banco. » Da allora ne tengo una all'anno, nell'armadio del laboratorio. Ventinove borse. Ma che l'avesse scritto qui, a suo figlio... non lo sapevo.", "반만 알았습니다, 부인. 97년에 사장님이 말로 하셨어요. '렌초, 우리 가방이 사라지게 두지 마라. 작업대 위에 늘 하나는 두거라.' 그때부터 해마다 하나씩 공방 장에 넣어 두었죠. 스물아홉 개. 그런데 그걸 여기에, 아드님한테 써 두셨는지는… 몰랐어요."),
(G, "Adesso lo sa.", "이제 아시잖아요."),
(R, "Adesso lo so. E l'ho lasciato vuoto da undici giorni.", "이제 압니다. 그리고 저는 그 자리를 11일째 비워 뒀고요."),
(GI, "Non è vuoto. Venerdì la zia ci ha dormito accanto.", "비어 있지 않아요. 금요일에 고모가 그 옆에서 잤어요."),
(R, "(guarda Giulia) La foto. Le chiavi e l'etichetta. Era tua l'idea?", "(줄리아를 보며) 그 사진. 열쇠랑 택. 네 생각이었니?"),
(GI, "Mia. La zia ha detto che era crudele.", "제 생각이요. 고모는 잔인하다고 했어요."),
(R, "Non era crudele. Era giusta. Non ho dormito per tutta la notte.", "잔인하지 않았어. 옳았지. 밤새 한숨도 못 잤다."),
(G, "C'è ancora la terza cosa, Renzo.", "아직 세 번째가 남았어요, 렌초."),
(R, "(rimette gli occhiali) « La terza: che quando i tuoi figli litigheranno — e litigheranno, perché sono Corsini — tu li faccia sedere a tavola la domenica, e che nessuno si alzi prima del dolce. »", "(다시 안경을 쓰며) '셋째, 네 아이들이 싸울 때—싸울 것이다, 코르시니니까—일요일에는 그 애들을 식탁에 앉히고, 디저트 전에는 아무도 일어나지 못하게 할 것.'"),
(G, "(ride, piangendo) Ecco da dove viene la regola del dolce. Io credevo che fosse di Paolo.", "(울면서 웃는다) 디저트 규칙이 여기서 온 거였군요. 파올로 규칙인 줄 알았는데."),

("#", "Scena 3 — Ore 12.30. La sala da pranzo.", "장면 3 — 낮 12시 30분. 식당."),
(None, "Chiara arriva con gli occhi stanchi, Matteo con il pane. La tavola è apparecchiata per sette: sei posti e, come sempre, quello di Paolo a capotavola. Il posto di Filippo resta vuoto, con il tovagliolo piegato.", "키아라는 피곤한 눈으로, 마테오는 빵을 들고 온다. 식탁은 일곱 명분이 차려져 있다. 여섯 자리와, 늘 그렇듯 상석의 파올로 자리. 필리포의 자리는 접힌 냅킨과 함께 비어 있다."),
(C, "(vede Renzo) Renzo...", "(렌초를 보고) 렌초…"),
(R, "Ciao, Chiara. Non dire niente ancora. Prima ascolta.", "안녕, 키아라. 아직 아무 말 하지 마. 먼저 들어."),
(M, "Ascoltare che cosa? Mamma, che succede?", "뭘 들어요? 엄마, 무슨 일이에요?"),
(G, "Sedetevi. Tutti. È domenica.", "앉아. 모두. 일요일이야."),
(C, "Che cos'è quel foglio, mamma?", "그 종이 뭐예요, 엄마?"),
(None, "Graziella legge lei, questa volta, le ultime righe. Renzo tiene il foglio.", "이번엔 그라치엘라가 마지막 몇 줄을 읽는다. 렌초가 종이를 들고 있다."),
(G, "« Una borsa ha tre padroni: chi la fa, chi la vende e chi la porta. Una famiglia ne ha uno solo: la tavola. »", "'가방에는 주인이 셋 있다. 만드는 사람, 파는 사람, 드는 사람. 가족에게는 주인이 하나뿐이다. 식탁.'"),
(C, "(piano) Il nonno diceva che la borsa aveva tre padroni. Non sapevo che ci fosse il resto.", "(작게) 할아버지가 가방에 주인이 셋 있다고 하신 건 알았어요. 뒷부분이 있는 줄은 몰랐어요."),
(G, "« Se un giorno uno dei ragazzi vorrà andare lontano, non chiudergli la porta. E se uno vorrà restare a guardia, non fargliela pesare. »", "'언젠가 아이들 중 하나가 멀리 가고 싶어 하면 문을 닫지 마라. 그리고 하나가 남아서 지키고 싶어 하면, 그걸 짐처럼 느끼게 하지 마라.'"),
(M, "(si blocca) Ma questa... questa è la frase del babbo. A Filippo. « Il piccolo andrà lontano. Tu tienigli la porta aperta. »", "(굳어 버리며) 근데 이건… 이건 아빠 말이에요. 형한테 하신. '막내는 멀리 갈 거다. 너는 문을 열어 둬라.'"),
(G, "Tuo padre l'ha presa da qui. L'ha imparata a memoria e l'ha detta a tuo fratello come se fosse sua.", "네 아빠가 여기서 가져간 거야. 외워 두셨다가 자기 말처럼 네 형한테 하신 거지."),
(C, "E poi? C'è ancora qualcosa?", "그다음은요? 더 있어요?"),
(G, "« Servono tutti e due: chi parte e chi tiene la porta aperta. Tuo padre, Ugo. »", "'둘 다 필요하다. 떠나는 사람도, 문을 열어 두는 사람도. 너의 아버지, 우고.'"),
(None, "Graziella posa il foglio accanto al piatto vuoto di Filippo.", "그라치엘라가 필리포의 빈 접시 옆에 종이를 내려놓는다."),
(C, "Filippo è quello che tiene la porta aperta. E noi giovedì gli abbiamo detto che era quello che chiude.", "필리포가 문을 열어 두는 사람이었네요. 그런데 우린 목요일에 문 닫는 사람이라고 했어요."),
(M, "Io gli ho detto peggio. Gli ho detto che la porta l'aveva chiusa il babbo e lui ci si era seduto davanti.", "난 더 심한 말을 했어. 아빠가 닫은 문 앞에 형이 주저앉아 있었던 거라고."),
(G, "Lo so. Vi sentivo dalla cucina.", "알아. 부엌에서 다 들렸어."),
(C, "Mamma, e l'offerta della Maison? Il quaranta per cento?", "엄마, 그럼 메종 제안은요? 40% 말이에요."),
(G, "La prima cosa della lettera è il timbro. Il loro quaranta per cento comprende il timbro?", "편지의 첫 번째가 도장이야. 그 사람들 40%에 도장도 들어가니?"),
(M, "Comprende il marchio. E il marchio, adesso, è il timbro del nonno: il logo di Chiara viene da lì.", "상표가 들어가요. 그리고 지금 상표는 할아버지 도장이에요. 키아라 로고가 거기서 나왔으니까."),
(C, "Allora la risposta l'ha già scritta lui. Nel novantasei.", "그럼 답은 할아버지가 이미 쓰셨네요. 96년에."),
(G, "La risposta la scriviamo noi, Chiara. Lui ci ha dato solo le domande giuste.", "답은 우리가 쓰는 거야, 키아라. 할아버지는 올바른 질문만 주신 거고."),
(R, "Signora, posso dire una cosa da operaio?", "부인, 일꾼으로서 한마디 해도 될까요?"),
(G, "Lei non è mai stato un operaio, Renzo. Dica.", "렌초는 일꾼이었던 적이 없어요. 말씀하세요."),
(R, "Il quaranta per cento non si vede su una borsa. Ma chi lo possiede, prima o poi, entra in laboratorio e sposta i banchi.", "40%는 가방에 안 보여요. 하지만 그걸 가진 사람은 언젠가 공방에 들어와서 작업대를 옮기죠."),
(M, "E Gaon? Anche loro vogliono una parte. Il quindici.", "그럼 가온은요? 그쪽도 지분을 원해요. 15%."),
(R, "Quindici o quaranta, un banco spostato è un banco spostato.", "15든 40이든, 옮겨진 작업대는 옮겨진 작업대야."),
(M, "Non è uguale, Renzo. Gaon vuole farci crescere, la Maison vuole tenerci piccoli.", "같지 않아요, 렌초. 가온은 우리를 키우려 하고, 메종은 우리를 작게 묶어 두려 해요."),
(C, "Matteo, non adesso. Non senza Filippo.", "마테오, 지금은 아니야. 필리포 없이는 안 돼."),
(M, "Hai ragione. (pausa) Hai ragione. È proprio la frase che giovedì nessuno di noi ha saputo dire.", "맞아. (잠시) 맞아. 그게 바로 목요일에 우리 중 누구도 하지 못한 말이야."),
(GI, "Allora decidete quando c'è anche il babbo. A tavola. Prima del dolce.", "그럼 아빠도 있을 때 정해요. 식탁에서. 디저트 전에."),
(G, "(si alza) Il dolce c'è. Ma oggi si mangia senza decidere niente. È la prima domenica in cui non decidiamo e mangiamo lo stesso.", "(일어서며) 디저트는 있어. 근데 오늘은 아무것도 정하지 않고 먹는 거야. 아무것도 정하지 않고도 밥을 먹는 첫 일요일이네."),
(R, "Il signor Ugo sarebbe contento. Diceva che le decisioni prese a stomaco vuoto sono sempre sbagliate.", "우고 사장님이 좋아하셨을 거예요. 빈속에 내린 결정은 늘 틀린다고 하셨거든요."),
(C, "(quasi ride) Questo nella lettera non c'è.", "(웃음이 날 뻔하며) 그건 편지에 없잖아요."),
(R, "No. Questo lo diceva a me, all'ora della merenda.", "없지. 그건 나한테 하신 말이야, 간식 시간에."),
(GI, "Il babbo deve leggerla.", "아빠가 이걸 읽어야 해요."),
(M, "Gliela leggo io al telefono.", "내가 전화로 읽어 줄게."),
(G, "No. Al telefono litighereste prima della seconda riga. Il bisnonno lo sapeva: per questo ha scritto.", "아니. 전화로 하면 둘째 줄도 가기 전에 싸울 거야. 증조할아버지도 그걸 아셔서 글로 쓰신 거야."),
(GI, "Allora la fotografo. Pagina per pagina. E gliela mando.", "그럼 제가 사진 찍을게요. 한 장 한 장. 그리고 보낼게요."),
(G, "Sì. Ma prima ci scrivo una riga io. Sotto quella di Paolo.", "그래. 근데 그 전에 내가 한 줄 쓸게. 파올로 글씨 밑에."),
(C, "Che cosa scrivi, mamma?", "뭐라고 쓰실 거예요, 엄마?"),
(G, "(prende la penna d'argento, scrive) « Tuo nonno l'ha scritta per tuo padre. Tuo padre l'ha tenuta per voi. La porta è aperta. Mamma. »", "(은빛 펜을 들어 쓴다) '네 할아버지가 네 아빠에게 쓰셨고, 네 아빠가 너희를 위해 간직했다. 문은 열려 있다. 엄마가.'"),
(M, "Niente « torna ».", "'돌아와'는 없네요."),
(G, "Niente « torna ». Una porta aperta non si spiega. Si lascia aperta.", "'돌아와'는 없어. 열린 문은 설명하는 게 아니야. 그냥 열어 두는 거지."),
(None, "Giulia fotografa le due pagine e il retro della busta. Manda tutto al padre. Poi posa il telefono a faccia in giù, accanto al pane.", "줄리아가 두 장과 봉투 뒷면을 찍는다. 전부 아빠에게 보낸다. 그리고 휴대폰을 빵 옆에 화면이 아래로 가게 엎어 놓는다."),
(GI, "Fatto. Adesso niente telefoni a tavola. Lo dice la nonna.", "보냈어요. 이제 식탁에서 휴대폰 금지. 할머니 규칙이에요."),
(G, "Lo diceva Ugo. Adesso lo sappiamo.", "우고 할아버지 규칙이었어. 이제 알았지."),

("#", "Scena 4 — Ore 16. Il laboratorio.", "장면 4 — 오후 4시. 공방."),
(None, "Il laboratorio è chiuso, è domenica. Chiara apre con le chiavi di Renzo. Renzo entra per primo. Si ferma davanti al suo banco: la lampada spenta, l'etichetta di venerdì ancora lì, accanto al posto vuoto delle chiavi.", "일요일이라 공방은 닫혀 있다. 키아라가 렌초의 열쇠로 연다. 렌초가 먼저 들어간다. 자기 작업대 앞에 멈춘다. 꺼진 램프, 열쇠가 놓였던 빈자리 옆에 아직 그대로인 금요일의 택."),
(R, "« Cucita da Simone — Controllata da Chiara. » (la prende) Hai controllato bene?", "'꿰맨 사람: 시모네 — 검사한 사람: 키아라.' (택을 집으며) 제대로 검사했니?"),
(C, "Quattro millimetri. E Loredana ha controllato me.", "4밀리미터요. 그리고 로레다나가 저를 검사했어요."),
(R, "Brava. Così si fa: anche chi controlla ha bisogno di qualcuno che lo controlli.", "잘했다. 그렇게 하는 거야. 검사하는 사람도 자기를 검사해 줄 사람이 필요하지."),
(C, "Renzo, le chiavi.", "렌초, 열쇠요."),
(R, "Non le voglio da te, Chiara.", "너한테서 받고 싶진 않구나, 키아라."),
(C, "(si irrigidisce) Perché?", "(굳으며) 왜요?"),
(R, "Perché me le ha date il signor Ugo, e il signor Ugo non c'è. Le prendo dalla signora.", "우고 사장님이 주신 거니까. 그런데 우고 사장님은 안 계시지. 부인께 받겠다."),
(None, "Chiara si volta. Graziella è sulla porta del laboratorio, in cappotto, con Giulia e Matteo dietro. Non entrava in laboratorio da quando è morto Paolo.", "키아라가 돌아본다. 공방 문간에 외투를 입은 그라치엘라가 서 있고, 줄리아와 마테오가 뒤에 있다. 파올로가 세상을 떠난 뒤로 그녀는 공방에 들어온 적이 없다."),
(G, "Me le dia, Chiara.", "열쇠 줘, 키아라."),
(C, "(gliele porge) Mamma, tu qui...", "(열쇠를 건네며) 엄마, 여기까지…"),
(G, "Sono la presidente. Ogni tanto la presidente deve entrare dove si lavora. (a Renzo) Renzo, sono di Ugo. E Ugo le ha date a Lei. Io sono solo la donna che gliele riporta.", "회장이잖아. 회장도 가끔은 일하는 곳에 들어와야지. (렌초에게) 렌초, 이건 우고 것이에요. 그리고 우고가 렌초에게 줬죠. 저는 다시 갖다 드리는 사람일 뿐이에요."),
(R, "(prende le chiavi) Signora, le ritiro le dimissioni. Ma a una condizione.", "(열쇠를 받으며) 부인, 사직서를 거두겠습니다. 하지만 조건이 하나 있어요."),
(G, "Quale?", "뭔데요?"),
(R, "Che domenica prossima ci sia anche Filippo a tavola. Non per me. Per il dolce.", "다음 일요일에 필리포도 식탁에 앉는 것. 저를 위해서가 아니라요. 디저트를 위해서요."),
(G, "Quella condizione non posso prometterla, Renzo. Posso solo apparecchiare.", "그 조건은 약속 못 해요, 렌초. 상만 차릴 수 있어요."),
(R, "Allora apparecchi. Il resto lo fa la lettera. Suo marito, l'ultimo inverno, me lo disse proprio qui: « Io ho dato da mangiare a tutti. Adesso tocca ai miei figli dare da vivere. »", "그럼 상을 차리세요. 나머지는 편지가 할 거예요. 남편분이 마지막 겨울에 바로 여기서 그러셨어요. '나는 모두를 먹여 살렸다. 이제 내 아이들이 살게 해 줄 차례다.'"),
(C, "E se la lettera non basta?", "편지로 안 되면요?"),
(None, "Renzo non risponde. Accende la lampada del suo banco. Si siede. Passa il pollice storto sul bordo di una borsa di prova. Giulia, dietro, non fotografa niente.", "렌초는 대답하지 않는다. 자기 작업대 램프를 켠다. 앉는다. 굽은 엄지로 시험용 가방의 가장자리를 쓸어 본다. 뒤에 선 줄리아는 아무것도 찍지 않는다."),
(M, "(a Giulia, piano) Non la fai, la foto?", "(줄리아에게 작게) 사진 안 찍어?"),
(GI, "No. Questa la tengo io.", "안 찍어요. 이건 제가 간직할 거예요."),
(None, "Nello stesso momento, a Parigi, su una panchina dei giardini del Lussemburgo, Filippo apre il telefono. Una foto dopo l'altra: la calligrafia di Ugo, la matita di Paolo, la penna d'argento della madre. Legge due volte. Poi chiude gli occhi.", "같은 시각, 파리 뤽상부르 공원의 벤치에서 필리포가 휴대폰을 연다. 사진이 차례로 넘어간다. 우고의 글씨, 파올로의 연필 글씨, 어머니의 은빛 펜 글씨. 두 번 읽는다. 그리고 눈을 감는다."),
]

